command:
// ==========================================
// LUNAS WIRKUNG: ANLEITEN (NURTI)
// SELBSTVERTRAUEN
//
// - mehrere Targets, ohne Reichweitenprüfung
// - gültige Ziele = Erfolg
// - ungültige Ziele = Misserfolg
// - gespeicherte Ziele, kein erneutes Target
// - eine gemeinsame Karte über Block 19.8
// - roter GM-Makrobutton über Block 19.8
// - direkte Effektanlage über Block 5
// - system.status.selfconfidence, Modus 2
// - Wert: QS / 2, kaufmännisch gerundet
// - kein zusätzlicher Status selfconfidence
// - alte Effekte nur für denselben Wirkenden ersetzen
// - Erfolgskontrolle prüft den tatsächlichen Systemwert
// - verarbeitete GM-Anfragen werden auch bei Misserfolg abgeschlossen
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Anleiten", vollerName = "Anleiten (Nurti) - Selbstvertrauen", ahne = "Nurti";
    const flagKey = "pendingAnleitenNurtiSelbstvertrauen";

    DSK_FW.EffektEnde.Register(
        "anleitenNurtiSelbstvertrauen",
        vollerName,
        "Das gestärkte Selbstvertrauen schwindet."
    );

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const dokument = await fromUuid(uuid);
            return dokument?.documentName === "Token" ? dokument.actor : dokument || null;
        } catch (error) {
            console.warn("Anleiten: Actor konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const findeAnleitenEffekte = (actor, casterUuid) =>
        (actor?.effects || []).filter(effect =>
            (effect.name || effect.label || "") === vollerName &&
            effect.getFlag("dsk", "isAnleitenSelbstvertrauen") === true &&
            effect.getFlag("dsk", "casterUuid") === casterUuid
        );

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    };

    // +++ 4 - EFFEKT DIREKT ÜBER BLOCK 5 ++++++++++++++++++++++

    const wendeSelbstvertrauenAn = async ({ casterActor, targetActor, qs, stufen, dauerMinuten }) => {
        if (!casterActor || !targetActor) return false;

        // Nur Effekte dieser Gabe und desselben Wirkenden ersetzen.
        const alteEffekte = findeAnleitenEffekte(targetActor, casterActor.uuid);
        if (alteEffekte.length) {
            await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
        }

        const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung:
                `Das Nurtikind stärkt das Selbstvertrauen des Ziels.` +
                `<br><br><b>Selbstvertrauen:</b> +${stufen} Stufe(n)` +
                `<br><b>Berechnung:</b> ${qs} QS / 2, kaufmännisch gerundet` +
                `<br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`,
            gabeZiel: "erwachte", qs,
            skills: ["system.status.selfconfidence"], key: "direkterSystemwert", formel: String(stufen),
            ziel: targetActor, duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime },
            flags: { dsk: {
                isAnleitenSelbstvertrauen: true, casterUuid: casterActor.uuid, qs, stufen
            }}
        });

        if (!erzeugterEffekt) return false;

        // Tatsächlichen Systemwert und Herkunfts-Flags kontrollieren.
        const korrekterSystemwert = (erzeugterEffekt.changes || []).some(change =>
            change.key === "system.status.selfconfidence" &&
            Number(change.mode) === 2 &&
            Number(change.value) === stufen
        );

        return (
            (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
            erzeugterEffekt.getFlag("dsk", "isAnleitenSelbstvertrauen") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(erzeugterEffekt.getFlag("dsk", "stufen")) === stufen &&
            korrekterSystemwert
        );
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN ++++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !game.user.isGM) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const stufen = Math.max(1, Math.round(qs / 2));
        const dauerMinuten = qs * 5;
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

        for (const ziel of daten.ziele || []) {
            const targetActor = await ladeActor(ziel.actorUuid);

            if (!targetActor) {
                misserfolge.push({ name: ziel.name || "Unbekanntes Ziel", grund: "Zielakteur wurde nicht gefunden" });
                continue;
            }

            if (!DSK_FW.Effekt.CheckTarget(targetActor, "erwachte")) {
                misserfolge.push({ name: ziel.name || targetActor.name, grund: "Kein Erwachter" });
                continue;
            }

            try {
                const effektErfolgreich = await wendeSelbstvertrauenAn({
                    casterActor, targetActor, qs, stufen, dauerMinuten
                });

                if (effektErfolgreich) {
                    erfolge.push({
                        name: `${ziel.name || DSK_FW.ResolveTokenName(targetActor)} – Selbstvertrauen +${stufen}`,
                        rolle: "Gestärktes Ziel"
                    });
                } else {
                    misserfolge.push({
                        name: ziel.name || targetActor.name,
                        grund: "Effekt konnte nicht angelegt werden"
                    });
                }
            } catch (error) {
                console.error("Anleiten: Effektanlage fehlgeschlagen.", { ziel, error });
                misserfolge.push({ name: ziel.name || targetActor.name, grund: "Effektanlage fehlgeschlagen" });
            }
        }

        const erfolgreich = erfolge.length > 0;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId, gabenName: vollerName, ahne,
            beschreibung: daten.beschreibung || "", wirkender: casterName,
            ziele: erfolge, misserfolge,
            dauerText: `${dauerMinuten} Minuten (${qs} QS × 5)`, erfolgreich
        });

        if (!erfolgreich) {
            ui.notifications.error("Luna sagt 🌙: Selbstvertrauen konnte auf kein Ziel angewendet werden!");
            return true; // Anfrage wurde verarbeitet und wird anschließend gelöscht.
        }

        ui.notifications.info(`Luna sagt 🌙: Selbstvertrauen wurde auf ${erfolge.length} Ziel(e) angewendet.`);
        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;
                if (await verarbeiteAnfrage(anfrageActor, daten)) await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
            return;
        }
    }

    // +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Anleiten Probe", "Anleiten", "Selbstvertrauen"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");
    }

    const stufen = Math.max(1, Math.round(qs / 2));
    const dauerMinuten = qs * 5;

    // +++ 8 - TARGETS PRÜFEN +++++++++++++++++++++++++++++++++++

    const targets = Array.from(game.user.targets);
    if (!targets.length) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");

    const gueltigeZiele = [], misserfolge = [];

    for (const targetToken of targets) {
        const targetActor = targetToken?.actor;
        const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Target";

        if (!targetActor) {
            misserfolge.push({ name: targetName, grund: "Kein gültiger Akteur" });
            continue;
        }

        if (!DSK_FW.Effekt.CheckTarget(targetActor, "erwachte")) {
            misserfolge.push({ name: targetName, grund: "Kein Erwachter" });
            continue;
        }

        gueltigeZiele.push({
            actorUuid: targetActor.uuid, tokenId: targetToken.id,
            tokenUuid: targetToken.document?.uuid || targetToken.uuid || null,
            name: targetName
        });
    }

    // +++ 9 - KEIN GÜLTIGES ZIEL ++++++++++++++++++++++++++++++

    const beschreibung =
        `Das Nurtikind stärkt das Selbstvertrauen der ausgewählten Ziele.` +
        `<br><br>Der Status Selbstvertrauen wird um <b>${stufen} Stufe(n)</b> erhöht.` +
        `<br><b>Berechnung:</b> ${qs} QS / 2, kaufmännisch gerundet` +
        `<br><b>Zielkategorie:</b> Erwachte`;

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
            ziele: [], misserfolge,
            dauerText: `${dauerMinuten} Minuten (${qs} QS × 5)`,
            gmBereich: false, angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 10 - GEMEINSAME KARTE ++++++++++++++++++++++++++++++++

    const gmLink = DSK_FW.GabenUI.GMMakroButton(macroUuid);

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: gueltigeZiele.map(ziel => ({
            name: `${ziel.name} – Selbstvertrauen +${stufen}`, rolle: "Gestärktes Ziel"
        })),
        misserfolge, dauerText: `${dauerMinuten} Minuten (${qs} QS × 5)`,
        gmLink, gmBereich: !game.user.isGM, anfragenderUserId: game.user.id
    });

    if (!nachricht) return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");

    // +++ 11 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName, qs, stufen, dauerMinuten,
        ziele: gueltigeZiele, misserfolge, beschreibung,
        sceneId: canvas.scene?.id || null, requestedByUserId: game.user.id,
        messageId: nachricht.id, macroUuid
    };

    // +++ 12 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);

    // +++ 13 - QS AUFRÄUMEN ++++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);
    ui.notifications.info("Luna sagt 🌙: Die Anwendung von Selbstvertrauen wurde bei der Spielleitung beantragt.");

}).call(this);
